pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(end < v.len(), "end must be within bounds");

    let mut best_val = v[0];
    let mut best_idx = 0usize;

    for i in 1..=end {
        let x = v[i];
        if x > best_val {
            best_val = x;
            best_idx = i;
        }
    }

    (best_val, best_idx)
}

pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(start < v.len(), "start must be within bounds");

    let mut best_val = v[start];
    let mut best_idx = start;

    for i in (start + 1)..v.len() {
        let x = v[i];
        if x < best_val {
            best_val = x;
            best_idx = i;
        }
    }

    (best_val, best_idx)
}

pub fn barrier(v: &[i32], p: usize) -> bool {
    debug_assert!(!v.is_empty(), "v must be non-empty");
    debug_assert!(p < v.len(), "p must be within bounds");

    // Vacuously true: no elements exist strictly to the right of p.
    if p + 1 >= v.len() {
        return true;
    }

    let (max_left, _) = find_max_in_prefix(v, p);
    let (min_right, _) = find_min_in_suffix(v, p + 1);

    max_left < min_right
}

